using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Linq;using UnityEngine;using Unity.Profiling;using AstroGateway.CinematicHUD;
namespace AstroGateway.ProductionVisual {public class ProductionPerformanceProbe:MonoBehaviour {
 public string output;public Action finished;IEnumerator Start(){var h=FindAnyObjectByType<AstroGatewayHUDController>();while(!h||!h.safe||!h.game.initialized)yield return null;h.game.testing=true;var lines=new List<string>{"Actual Editor batch Play Mode; four presets, stationary spawn, clear weather, full HUD. 1920x1080 requested framebuffer; 2s warmup + >=4s samples per preset.","Unity="+Application.unityVersion+" GPU="+SystemInfo.graphicsDeviceName+" API="+SystemInfo.graphicsDeviceType,"Capped cadence and whole-Editor Main Thread recorder are not isolated CPU work, GPU timing or physical Android performance."};using(var cpu=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread",1))using(var batches=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Batches Count",1))using(var triangles=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Triangles Count",1))using(var gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame",1)){
 for(int q=0;q<4;q++){h.environment.ApplyQuality(q);yield return new WaitForSecondsRealtime(2);var dt=new List<double>();var c=new List<double>();var b=new List<long>();var t=new List<long>();var g=new List<long>();double start=Time.realtimeSinceStartupAsDouble,prev=start;while(Time.realtimeSinceStartupAsDouble-start<4){yield return null;double now=Time.realtimeSinceStartupAsDouble;dt.Add((now-prev)*1000);prev=now;if(cpu.Valid&&cpu.LastValue>0)c.Add(cpu.LastValue/1e6);if(batches.Valid&&batches.LastValue>0)b.Add(batches.LastValue);if(triangles.Valid&&triangles.LastValue>0)t.Add(triangles.LastValue);if(gc.Valid)g.Add(gc.LastValue);}dt.Sort();lines.Add("preset="+new[]{"Low","Medium","High","Desktop/Ultra Preview"}[q]+" framebuffer="+Screen.width+"x"+Screen.height+" frames="+dt.Count+" sample_valid="+(dt.Max()<2000)+" mean_ms="+dt.Average().ToString("F2")+" p95_ms="+dt[(int)(dt.Count*.95)].ToString("F2")+" max_ms="+dt.Max().ToString("F2")+" effective_fps="+(1000/dt.Average()).ToString("F2")+" MainThread_ms="+(c.Count>0?c.Average().ToString("F2"):"unavailable")+" batches="+(b.Count>0?b.Average().ToString("F1"):"unavailable")+" triangles="+(t.Count>0?t.Average().ToString("F0"):"unavailable")+" GC_bytes_per_frame="+(g.Count>0?g.Average().ToString("F0"):"unavailable")+" allocated_memory_bytes="+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong());}}
 lines.Add("GPU timing unavailable; counters if present include whole Editor rendering, not scene-only/player attribution. No performance improvement or mobile readiness claim.");File.WriteAllLines(output,lines);finished?.Invoke();}
 }}
#endif
